package kernels

// gemm32 is the float32 GEMM on an RVV kernel (gemmMicro8x16RVV or
// gemmMicro6x16RVV in sum_riscv64.s, generated by go-asmgen; see
// asmgen/riscv64/gen.go). Without the V extension there is none, and float32
// products are computed in float64.
var gemm32 = newGemm32(useRVV)

// gemm32WideVLEN is the vector register length in bytes from which the 8x16
// kernel runs: with E32 and LMUL=2 it needs vl = 16, which a group of two
// registers holds only when VLEN >= 256. A var so tests can pin the narrow
// kernel on a wide core.
var gemm32WideVLEN = 32

// vlenb is the vector register length in bytes (0 without the V extension).
var vlenb = func() int {
	if !useRVV {
		return 0
	}
	return gemmVLENB()
}()

func newGemm32(rvv bool) *gemmKernel[float32] {
	if !rvv {
		return nil
	}
	if vlenb >= gemm32WideVLEN {
		return &gemmKernel[float32]{mr: 8, nr: 16, micro: gemmMicro32x8}
	}
	return &gemmKernel[float32]{mr: 6, nr: 16, micro: gemmMicro32}
}

// gemmMicro32 adds the 6 x 16 tile sum_p pa[p*6..]*pb[p*16..] into the C block
// at dst[0:], whose rows are ldc apart. pa, pb hold at least kc*6 and kc*16
// packed (zero-padded) floats; dst has at least 5*ldc + 16 elements.
func gemmMicro32(kc int, pa, pb, dst []float32, ldc int) {
	_, _, _ = pa[kc*6-1], pb[kc*16-1], dst[5*ldc+15] // the kernel's whole reach
	gemmMicro6x16RVV(kc, &pa[0], &pb[0], &dst[0], ldc)
}

// gemmMicro32x8 is gemmMicro32 for the 8 x 16 tile: pa holds at least kc*8
// floats, dst at least 7*ldc + 16 elements.
func gemmMicro32x8(kc int, pa, pb, dst []float32, ldc int) {
	_, _, _ = pa[kc*8-1], pb[kc*16-1], dst[7*ldc+15] // the kernel's whole reach
	gemmMicro8x16RVV(kc, &pa[0], &pb[0], &dst[0], ldc)
}

//go:noescape
func gemmMicro6x16RVV(kc int, pa, pb, c *float32, ldc int)

//go:noescape
func gemmMicro8x16RVV(kc int, pa, pb, c *float32, ldc int)

// gemmVLENB returns the vector register length in bytes. It requires V.
func gemmVLENB() int
